package cn.local.rainreminder;
import android.app.*;import android.app.job.*;import android.content.*;import org.json.*;import java.util.*;

final class ClassWatch {
 static final int JOB=2021;
 static boolean enabled(Context c){return Store.prefs(c).getBoolean("watchOpenClass",true)&&Store.prefs(c).getLong("last",0)>0;}
 static void schedule(Context c){JobScheduler jobs=c.getSystemService(JobScheduler.class);if(!enabled(c)){jobs.cancel(JOB);return;}if(jobs.getPendingJob(JOB)==null)jobs.schedule(new JobInfo.Builder(JOB,new ComponentName(c,ClassWatchJob.class)).setPeriodic(15*60*1000L).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).build());}
 static JSONArray check(Context c)throws Exception{JSONObject response=CourseApi.get("https://changjiang.yuketang.cn/api/v3/classroom/on-lesson-upcoming-exam");return accept(c,response);}
 static synchronized JSONArray accept(Context c,JSONObject response)throws Exception{if(!enabled(c))return new JSONArray();if(response.optInt("code",-1)!=0||!response.has("data"))throw new java.io.IOException("开课接口未授权或发生变化");JSONArray raw=response.getJSONObject("data").optJSONArray("onLessonClassrooms");if(raw==null)throw new java.io.IOException("开课列表格式发生变化");JSONArray active=students(raw);long now=System.currentTimeMillis();android.content.SharedPreferences p=Store.prefs(c);android.content.SharedPreferences.Editor edit=p.edit();for(String key:p.getAll().keySet())if(key.startsWith("seenLesson_")&&p.getLong(key,0)<now-7*86400000L)edit.remove(key);
  for(int i=0;i<active.length();i++){JSONObject item=active.getJSONObject(i);String key="seenLesson_"+item.optString("lessonId");if(p.contains(key)||!allowed(c,item.optString("courseName")))continue;notify(c,item);edit.putLong(key,now);}edit.putString("openClasses",active.toString()).putLong("classWatchLast",now).remove("classWatchError").commit();return active;}
 static JSONArray students(JSONArray raw)throws Exception{JSONArray out=new JSONArray();for(int i=0;i<raw.length();i++){JSONObject e=raw.getJSONObject(i);int role=e.optInt("role",-1);String id=e.optString("lessonId");if(role<0||role==1||role==2||!id.matches("[0-9]+")||e.optString("courseName").isEmpty())continue;out.put(e);}return out;}
 static boolean allowed(Context c,String title){JSONArray events=Agenda.all(c);boolean found=false,allow=false;for(int n=0;n<events.length();n++){JSONObject e=events.optJSONObject(n);if(e!=null&&e.optBoolean("course")&&e.optString("title").equals(title)){found=true;allow|=e.optBoolean("liveReminder",e.optInt("scanLead",3)>=0);}}return !found||allow;}
 static void notify(Context c,JSONObject item){String id=item.optString("lessonId");NotificationManager nm=c.getSystemService(NotificationManager.class);Agenda.channel(c);PendingIntent open=PendingIntent.getActivity(c,7003,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String body="老师已开课，请查看是否需要扫码；由你手动完成。";Notification n=new Notification.Builder(c,Agenda.CHANNEL).setSmallIcon(c.getApplicationInfo().icon).setContentTitle("老师已开课 · "+item.optString("courseName")).setContentText(body).setContentIntent(open).setAutoCancel(true).setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PRIVATE).build();try{nm.notify(("open:"+id).hashCode(),n);}catch(SecurityException ignored){}}
}
